<?php
declare(strict_types=1);
require_once getenv('TEACHER_PLATFORM_BOOTSTRAP') ?: '/websites/_protected/teacher-platform-v1/app/bootstrap.php';
use ReligionPlatform\Auth;
use ReligionPlatform\Identity;
use ReligionPlatform\Modules;
use ReligionPlatform\Portal;
use ReligionPlatform\SchoolDirectory;
use ReligionPlatform\Security;

Security::headers("default-src 'self'; img-src 'self' data:; style-src 'self'; script-src 'none'; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'");
Security::startSession();
$error='';
if(($_SERVER['REQUEST_METHOD'] ?? 'GET')==='POST') {
    try {header('Location: '.Portal::action($_POST,$_FILES),true,303);exit;}
    catch(Throwable $exception) {
        $error=$exception instanceof PDOException?'Die Angaben konnten nicht gespeichert werden. Bitte Anmeldename und Listennummer auf doppelte Einträge prüfen.':$exception->getMessage();
    }
}
$identity=Identity::current();
$teacher=$identity && $identity['kind']==='teacher'?Auth::currentUser(null):null;
$admin=$identity && $identity['role']==='admin';
$next=Portal::next($_GET['next'] ?? $_POST['next'] ?? null);
$personal=(string)($_GET['person'] ?? '');
if(preg_match('/^[a-f0-9]{32}$/D',$personal)) {
    $q=ReligionPlatform\Database::connection()->prepare('SELECT l.username,o.slug FROM platform_learners l JOIN organisations o ON o.id=l.organisation_id WHERE l.subject=? AND o.status="active"');
    $q->execute([$personal]);
    if($prefill=$q->fetch()) {$_GET['schule']=$prefill['slug'];$_GET['u']=$prefill['username'];}
}
$view=(string)($_GET['view'] ?? 'home');
$once=$_SESSION['shared_portal_once'] ?? [];unset($_SESSION['shared_portal_once']);
$rosterCredentials=$_SESSION['shared_roster_credentials'] ?? [];unset($_SESSION['shared_roster_credentials']);
$pendingRoster=$_SESSION['shared_roster_preview'] ?? null;
$previewToken=(string)($_GET['roster_preview'] ?? '');
if(!is_array($pendingRoster) || ($pendingRoster['expires_at'] ?? 0)<time() || !$previewToken || !hash_equals((string)($pendingRoster['token'] ?? ''),$previewToken)) $pendingRoster=null;
$h=static fn($v)=>Security::h((string)$v);
function fields(string $action): void {echo '<input type="hidden" name="csrf" value="'.Security::h(Security::csrf()).'"><input type="hidden" name="action" value="'.Security::h($action).'">';}
?>
