<?php if($rosterCredentials): ?><section class="panel one-time"><h2><?= count($rosterCredentials) ?> neue Schülerzugänge</h2><p>Die Startpasswörter werden nur jetzt angezeigt. Bitte sicher ausgeben oder ausdrucken.</p><div class="table-wrap"><table><thead><tr><th>Anmeldename</th><th>Startpasswort</th><th>Persönlicher Einstieg</th></tr></thead><tbody><?php foreach($rosterCredentials as $credential): ?><tr><td><code><?= $h($credential['username']) ?></code></td><td><code><?= $h($credential['start_password']) ?></code></td><td><small><?= $h($credential['url']) ?></small></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
