 else: ?><form method="post"><?php fields('roster_import'); ?><input type="hidden" name="preview_token" value="<?= $h($pendingRoster['token']) ?>"><button class="primary">Geprüfte Liste verbindlich anlegen</button></form><?php endif; ?></section><?php endif; ?></details><?php endif; ?>
